/* ============================================================
   PDF · las otras letras de la app (Apariencia › Tu pantalla › Letra): Newsreader, Instrument Sans, Archivo Narrow,
   Bricolage Grotesque, Rubik y Shantell Sans (SIL Open Font License 1.1), regular y negrita, solo con los caracteres
   latinos que dejan pasar los PDF (pdfSafe) y sin «hinting». Se incrustan solo si se eligió esa letra.
   Lo arma tools/fuentes.py (no editar a mano).
   ============================================================ */
const PDF_FONTS_X = {
  newsreader: { normal: '', bold: '' },
  instrument: { normal: '', bold: '' },
  narrow: { normal: '', bold: '' },
  bricolage: { normal: '', bold: '' },
  rubik: { normal: '', bold: '' },
  shantell: { normal: '', bold: '' },
};
/* la letra elegida en este documento (se incrusta una vez): devuelve su nombre o '' si no hay o falla */
function pdfFontX(doc, key) {
  if (!key || !PDF_FONTS_X[key]) return '';
  doc._fx = doc._fx || {};
  if (doc._fx['x:' + key] != null) return doc._fx['x:' + key];
  try {
    for (const [st, b] of Object.entries(PDF_FONTS_X[key])) { doc.addFileToVFS(`${key}-${st}.ttf`, b); doc.addFont(`${key}-${st}.ttf`, 'fx-' + key, st); }
    return (doc._fx['x:' + key] = 'fx-' + key);
  } catch (e) { console.warn('PDF: no se pudo incrustar la letra', key, e); return (doc._fx['x:' + key] = ''); }
}
